// Brand SVGs by file name, resolved to URLs at build time. Source: brand/project/assets (generated by brand/gen.py).
const urls = (files: Record<string, string>) =>
  Object.fromEntries(Object.entries(files).map(([path, url]) => [path.split('/').pop()!.replace('.svg', ''), url]));

export const productIcon = urls(
  import.meta.glob<string>('../../brand/project/assets/Product-icons/*.svg', { eager: true, query: '?url', import: 'default' }),
);
export const illustration = urls(
  import.meta.glob<string>('../../brand/project/assets/Illustrations/*.svg', { eager: true, query: '?url', import: 'default' }),
);
export const logo = urls(
  import.meta.glob<string>('../../brand/project/assets/Logos/*.svg', { eager: true, query: '?url', import: 'default' }),
);
